// Data: approved recipe account-contact (steps Account, Contact), cleaned up after the test
// Note: Pre-existing Contact email from recipe (<EMAIL_5>) is used as the email for the duplicate contact test.
// Note: Clicking Save twice handles the Salesforce duplicate warning dialog flow (first click triggers warning, second click confirms and saves).
import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { ContactRecordPage } from '../../pages/ContactRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectRecordTitle, recordIdFromView, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Duplicate contact warning shown when saving Contact with same Email on same Account', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-050 Duplicate contact warning shown when saving Contact with same Email on same Account',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-050',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const contactRecordPage = new ContactRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Navigate to the Account record page and click New Contact', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): New Contact modal opens with Account Name pre-populated
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.accountId).toHaveValue(data.value('Account', 'Name'));
      });
      await test.step("2. Enter First Name 'Test', Last Name 'Duplicate', Email same as existing Contact, then click Save", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): A possible duplicate warning is displayed indicating a Contact with the same Email already exists on this Account; the Save button remains enabled
        await newContactDialog.firstName.fill('Test');
        await newContactDialog.lastName.fill('Duplicate');
        await newContactDialog.email.fill(data.value('Contact', 'Email'));
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expect(newContactDialog.saveButton).toBeVisible();
      });
      await test.step('3. Click Save on the duplicate warning dialog to confirm saving the duplicate Contact', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): The Contact record is saved and the Contact detail page opens showing the entered Last Name 'Duplicate' and Email 'duplicate@test.com'
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        viewed['newContact'] = await recordIdFromView(page, 'Contact');
        await data.adoptCreated('newContact', 'Contact', viewed['newContact']);
        await expectRecordTitle(page, 'Duplicate');
        await expect(contactRecordPage.emailField).toContainText(data.value('Contact', 'Email'));
      });
      await test.step('4. Verify via SOQL that the duplicate Contact was saved on the Account with Email', async () => {
        // Expected (DECLARED_CONFIG; OC-005, DuplicateRule:Contact.Contact_Same_Email_Same_Account, BRD-CON-012#BR-10): SOQL query confirms the new Contact record exists on the Account with Email 'duplicate@test.com' alongside the pre-existing Contact
        await expect
          .poll(() => soqlValue(sf, 'Contact', viewed['newContact'] ?? '', 'Email'))
          .toBe(data.value('Contact', 'Email'));
      });
      await test.step('5. Confirm the test case MTC-009 passes regression verification', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4, BRD-CON-012#BR-10): Test execution result shows PASS for the duplicate warning scenario, confirming RE_VERIFY status is satisfied
        await expect
          .poll(() => soqlValue(sf, 'Contact', viewed['newContact'] ?? '', 'AccountId'))
          .toBe(data.id('Account'));
      });
    },
  );
});
